     "artist": "保罗·博德里",
     "artistId": "baudry",
     "year": 1860,
     "yearLabel": "1860",
     "school": "学院派",
     "medium": "布面油画",
     "dims": "106.5 × 83.5 cm",
     "workCount": 1,
     "intro": [
      "按时间顺序，这部分的第一件作品是保罗·博德里（Paul Baudry）的玛德莱娜·布罗昂。创作于1860年，长83.5 cm，高106.5cm。",
      "博德里是一位学院派画家，1850年获得罗马大奖留学意大利，在此期间尤其受到文艺复兴画家柯勒乔的影响。他仅画过少量历史画，就将事业重心转入肖像画的创作中。画中的女子玛德莱娜·布罗昂是当时法国的知名演员。出道不到两年便荣升法兰西喜剧院院长。"
     ],
