     "intro": [
      "埃内斯特·迪埃（Ernest Duez）的于利斯·比坦，完成于1880年，高155cm，长135cm。",
      "迪埃是一位风俗、风景和肖像画家，他是马奈的崇拜者，收藏过马奈、莫奈、德加、莫里索等新锐画家的作品。但他的风格不如印象派那么接近，用色也更为柔和。此画描绘的于利斯·比坦是当时的一位自然主义艺术家，热衷海滨题材。这幅不同寻常的肖像就捕捉了艺术家创作的瞬间。"
     ],
