     "id": "e011",
     "order": 6,
     "name": "朱尔·达卢",
     "artist": "奥古斯特·罗丹",
     "artistId": "rodin",
     "year": 1883,
     "yearLabel": "1883 前后",
     "school": "现实主义雕塑",
     "medium": "青铜",
     "dims": "高 54.5 cm",
     "workCount": 1,
     "intro": [
      "著名雕塑家奥古斯特·罗丹（Auguste Rodin）的朱尔·达卢，完成于1883年前后，高54.5cm。",
      "罗丹被誉为现代雕塑的奠基者。他早年的艺术生涯并不顺利，二十多岁时，他师从以动物雕塑闻名的安托万-路易·巴里，后前往意大利旅游，并受到米开朗基罗和多纳泰罗影响。之后，罗丹逐渐发展出自己的风格，借鉴绘画的创作手法，强调光影的作用，人物神态生动，且富有力量。",
      "这件雕塑表现的朱尔·达卢，也是当时著名的雕塑家。他是卡尔波的学生，也是罗丹和方丹-拉图尔的好友。达卢参加过巴黎公社，也是工人阶级的同情者，他本人的风格则倾向于现实主义。达卢也是法国国家美术协会的创始人之一。"
     ],
