     "intro": [
      "罗丹的维克多·雨果，完成于1897年，高70.6cm。",
      "罗丹自年轻时就对雨果满怀敬仰。1883年，罗丹第一次见到雨果本人，很快他便为雨果创作了一尊胸像，与本次展览中的朱尔·达卢胸像一同亮相于1884年的沙龙展。",
      "本次奥赛展展出的雨果胸像以1885年雨果去世后罗丹为其设计的纪念碑为蓝本，并有所改动。雨果的胸膛充满英雄气概，象征着毫不动摇的力量；低垂的头颅和紧闭的双眼，则体现出雨果深邃活跃的视线。"
     ],
