     "intro": [
      "库尔贝的皮埃尔-约瑟夫·蒲鲁东画像，完成于1865年，高72.3cm，长55.5cm。",
      "库尔贝一直以来就对政治十分热衷。他在来到巴黎后不久就成为塞纳河左岸咖啡馆的意见领袖，结识了蒲鲁东、波德莱尔等先锋人物。他后来还短暂参加了巴黎公社，负责博物馆的开放和沙龙的组织工作。库尔贝开创性的观点和不妥协的做法，使其获得了许多印象派画家的崇拜。",
      "至于这幅画中的普鲁东，他是法国的社会主义者，也被认为是无政府主义的创始人。提倡用联邦契约制取代国家以及任何集中制的共同体。他最著名的一句口号是：“财产就是盗窃！”"
     ],
