     "id": "e022",
     "order": 10,
     "name": "一次碰头",
     "artist": "玛丽·巴什基尔采夫",
     "artistId": "bashkirtseff",
     "year": 1884,
     "yearLabel": "1884",
     "school": "自然主义",
     "medium": "布面油画",
     "dims": "195 × 177 cm",
     "workCount": 1,
     "intro": [
      "勒帕热描绘农村，他的好友玛丽·巴什基尔采夫（Marie Bashkirtseff）则把目光转向城市景观。其代表作一次碰头就是如此。此画创作于1884年，高195cm，长177cm。",
      "巴什基尔采夫是本次奥赛展中唯一的女性艺术家。她出身乌克兰的贵族家庭，年轻时父母离异，后跟随母亲游历了欧洲各地，最终定居巴黎。她是当时极少数进入美院学习的女性之一。",
      "此画描绘街道中相会的6个小男孩，他们穿着破旧，显然来自工人阶层。画家生动刻画了孩子们生动的表情，身上的罩衫则表明他们是小学生。当时，茹费理推动了免费义务教育，让穷人家的孩子也可以上学读书。作为一名女权主义者，画家似乎还在画中表达了她的政治观点。后方的小女孩背身走去，似乎被排斥在碰面之外。",
      "一次碰头在1884年的沙龙展上获得了公众和媒体的一致好评，但并没有获奖。这让巴什基尔采夫感到不公正和愤怒。她在同年死于肺结核，年仅25岁，和好友勒帕热在同一年去世。"
     ],
