      "第一件是亚历山大·法尔吉埃（Alexandre Falguière）的摔跤手。并不是雕塑，而是油画，完成于1875年，高231.4cm，长178.7cm。",
      "法尔吉埃出身工匠家庭，1859年考取罗马大奖，前往意大利留学。后来入选法兰西艺术院，培养出布德尔等学生。他也进行油画创作，风格属于现实主义一派。",
      "摔跤手是法尔吉埃创作的第一幅大型画作，在同年的沙龙展上获得了二等奖。在浪漫主义时代，摔跤手成为流行主题，而在普法战争后，摔跤手又被赋予勇气和战斗精神的含义。"
