     "id": "e027",
     "order": 3,
     "name": "海滩上",
     "artist": "爱德华·马奈",
     "artistId": "manet",
     "year": 1873,
     "yearLabel": "1873",
     "school": "印象派",
     "medium": "布面油画",
     "dims": "60 × 73.5 cm",
     "workCount": 1,
     "intro": [
      "海滩上，完成于1873年，高60cm，长73.5cm。",
      "此画创作于马奈和家人在海滨小镇度假期间。他让妻子和弟弟欧仁在沙滩上摆好姿势，自己用画笔记录下这一场景。画中的两人背对观众，似乎沉浸在自己的世界中，带来一丝难以言喻的忧郁感。",
      "马奈使用的色彩不多，包括经典印象派回避的黑色和灰色，他从印象派画家中借鉴了流畅、轻盈的笔触。此画看起来是快速完成的，海水颜色的渐变通过水平色条来呈现。整幅画看起来缺乏深度，色彩平面，可能体现了马奈受日本浮世绘的影响。"
     ],
