      "上啤酒的女招待，创作于1878或1879年，高77cm，长64.5cm。",
      "1874年，马奈着手创作一幅大型油画，描绘Reichshoffen啤酒屋的音乐会咖啡馆。咖啡馆的女服务员令马奈着迷，他改变了计划，将画作分为两部分，分别进行创作。此画和另一幅描绘咖啡馆音乐会女招待的画作密切相关，可能是它的另一版本或习作。"
