     "id": "e033",
     "order": 9,
     "name": "L.L.小姐肖像",
     "artist": "詹姆斯·蒂索",
     "artistId": "tissot",
     "year": 1864,
     "yearLabel": "1864",
     "school": "新绘画",
     "medium": "布面油画",
     "dims": "123.5 × 99 cm",
     "workCount": 1,
     "intro": [
      "詹姆斯·蒂索（James Tissot）的L.L.小姐肖像，完成于1864年，高123.5cm，宽99cm。",
      "蒂索是德加和马奈的好友，年纪比他们略小一些。蒂索出身商人家庭，曾受教于安格尔，正是在这一时期，他认识了马奈、德加、惠斯勒等艺术家。他尝试将现实主义、印象派和学院派艺术元素融入自己的作品中，以其描绘欧洲上流阶层的风俗画闻名。",
      "蒂索早年凭借散发着古朴和感伤色彩中世纪题材画作声名鹊起。自1864年起，他的风格一变，开始在肖像和风俗画中以辛辣笔触评判当时的风尚。",
      "这幅画中的年轻女子，虽置身与其社会地位相符的环境中，但那挑衅的神态却与传统资产阶级肖像画的惯例和礼仪相去甚远。无论是她稍显随意的坐姿，还是略微侧首显露的风情，都难称端庄。而裙摆间若隐若现的粉色便鞋，更凸显了画中人的独立精神。从此以后，无拘无束的巴黎女性成为蒂索画作中的常见主题。"
     ],
