     "intro": [
      "阿尔弗雷德·史蒂文斯（ Alfred Stevens ）的沐浴，创作于约1873年，高73.5cm，宽92.8cm。",
      "史蒂文斯来自比利时的艺术家庭，父亲是收藏家，母亲经营着一家颇具声名的咖啡馆。1843年，他考入巴黎美术学院，之后逐渐融入巴黎的艺术圈，成为马奈、德加、惠斯勒、莫里索、波德莱尔等人的好友。史蒂文斯以描绘当代女性的优雅画作闻名，也像同时代的一些画家那样，受到日本艺术和印象派的影响。"
     ],
