     "intro": [
      "亨利·热尔韦（Henri Gervex）的瓦尔泰丝·德·拉·比涅夫人，完成于1879年，高205cm，宽102.2cm。",
      "热尔韦是卡巴内尔的学生，早年作品大多是和老师卡巴内尔类似的神话题材。1876年，热尔韦结识了马奈和一些印象派画家，在他们的影响下，他的画风变得更加轻盈、明亮。他也和之前提到的阿尔弗雷德·史蒂文斯一起绘制了巨幅画作世纪史。",
      "画中的瓦尔泰丝·德·拉·比涅夫人是当时著名的演员和交际花。她虽然出身工人阶层，却因其美貌和大胆钻营，跻身巴黎的精英阶层。比涅夫人是热尔韦的诸多情人之一，也是马奈、左拉的缪斯女神。据说左拉的小说《娜娜》，原型就是这位书写自己人生的女子。"
     ],
