      "贝纳尔早年就读于巴黎美术学院，如同学院派画家那样，考取罗马大奖，去意大利留学。1880年前后，他开始受到印象派的影响，将印象派对光线的表现及其技术应用于自己的作品中。他在英国期间师法庚斯博罗、雷诺兹，为自己的肖像，特别是女性肖像增添了一丝英国色彩。"
