     "intro": [
      "维特伊的教堂，创作于1879年，高65.5cm，长50.5cm。",
      "1878年，莫奈搬到了巴黎西北的维特伊村，和热爱艺术的百货店主埃内斯特·奥舍德一家合租在一起。此时，莫奈的妻子卡米尔已确诊为子宫癌晚期，第二个孩子的出生更加重了他的经济的负担。第二年，妻子去世，莫奈的人生陷入低谷。",
      "在维特伊期间，莫奈继续对自然元素的研究。可能是受人生境遇影响，莫奈放弃了阿让特伊期间对当代生活和休闲场景的兴趣，专注于捕捉自然中最易逝的一面。画中这座教堂始建于12世纪，带有哥特风格，是维特伊的地标建筑，在当时已经是有名的历史古迹。莫奈在此期间多次描绘了这座教堂。"
     ],
