     "id": "e040",
     "order": 3,
     "name": "贝勒岛荒野海岸的岩石",
     "artist": "克劳德·莫奈",
     "artistId": "monet",
     "year": 1886,
     "yearLabel": "1886",
     "school": "印象派",
     "medium": "布面油画",
     "dims": "65.5 × 81.5 cm",
     "workCount": 1,
     "intro": [
      "贝勒岛荒野海岸的岩石，创作于1886年，高65.5cm，长81.5cm。",
      "莫奈一直在寻找新的风景和氛围，1886年秋天，他来到贝勒岛。这是布列塔尼群岛中最大的岛屿，之前鲜有艺术家光顾。这里的天气变幻莫测，贝勒岛和它那荒无人烟的海岸线激发了莫奈心中复杂的情感。他在给好友卡耶博特的信中写到：“我现在身处一个绝美荒凉之地，有令人生畏的岩石滩，还有一片五光十色、不可思议的海洋，总之，我兴奋至极，但也不知所措，因为我已经习惯了在拉芒什海峡作画，并且有了一套自己的方法，但大西洋却完全不同。”",
      "这一时期，莫奈的作品风格发生转变，形体更为凝练，布局也更具张力，同时还能看出日本浮世绘大师铃木春信和葛饰北斋的影响。此画的地平线位于画作顶部，几乎没有给天空留下空间。强烈的色彩呈现出大海凶险的氛围。，莫奈采用不同以往的平坦而宽阔的笔触，如同抑扬顿挫的符号，表现出这座岛屿的令人敬畏之处。"
     ],
