     "id": "e043",
     "order": 6,
     "name": "马尔利勒鲁瓦镇的砖厂小路",
     "artist": "阿尔弗雷德·西斯莱",
     "artistId": "sisley",
     "year": 1876,
     "yearLabel": "约 1876",
     "school": "印象派",
     "medium": "布面油画",
     "dims": "55 × 46 cm",
     "workCount": 1,
     "intro": [
      "马尔利勒鲁瓦镇的砖厂小路，创作于约1876年，高55cm，长46cm。",
      "西斯莱对风景的热爱与生俱来，他留下的作品几乎都是风景画，画中的人物只有剪影，作为风景的点缀。他曾写道：“万物在丰饶肥沃的大气中呼吸、繁茂，这种大气分配并平衡光线，营造出和谐。”他反复描绘着生活场所周遭的风景，以及季节和光影的变化。此画正如西斯莱的大多数作品那样，充满宁静祥和的氛围，也彰显着画家本人的个性。"
     ],
