     "yearLabel": "1882",
     "school": "印象派",
     "medium": "布面油画",
     "dims": "82 × 66 cm",
     "workCount": 1,
     "intro": [
      "开花的树，创作于1882年，高82cm，长66cm。",
      "古斯塔夫·卡耶博特出身巴黎的中上阶层家庭，家境富裕，本人既拥有律师资格，又是名工程师。卡耶博特是马奈、德加，以及很多印象派画家的朋友。他在莫奈、毕沙罗等人生活拮据的时刻，给了朋友们必要的经济资助，也收藏了不少他们的作品。事实上，本次展览中的一些画作原本就是卡耶博特的收藏。",
      "卡耶博特在莱昂·博纳的画室中接受了专业教育，本人也是名出色的画家。他参加过印象派的画展，其风格相对更现实主义。他也是最早一批深入研究摄影的艺术家之一。卡耶博特描绘了许多城市生活和家庭场景，此画是他描绘乡村场景的作品。它采用了相对柔和的印象派风格，令人想起雷诺阿的画作。"
     ],
