     "intro": [
      "读书的女人，创作于1874-1876年，高46.5cm，宽38.5cm。",
      "雷诺阿生于法国的瓷都利摩日。3岁那年，雷诺阿全家搬到巴黎寻求发展，由于家境拮据，他13岁就不得不中断学业，到瓷器厂去当学徒。几年后，雷诺阿开始正式学画，此时，机械复制已经取代了传统的瓷器绘画，为了筹措学费，雷诺阿尝试过多种艺术工作，练就了熟练的绘画技巧。",
      "相较大多数印象派画家，雷诺阿的作品从一开始就更受人们欢迎。早在1864年，他就有作品入选官方沙龙，在第一次印象派画展上，雷诺阿的作品相对也更受好评。肖像和人体是雷诺阿长久以来的兴趣所在，在艺术生涯早期，他希望通过肖像画来维持生计，此画就是这一时期的作品。",
      "19世纪中叶，越来越多巴黎女性学会读书写字，画家们也开始记录下女性读书的瞬间。画中的女性不再是传统绘画中被观看的对象，也不再只是母亲或者妻子，而是认真、独立、具有文化品位的现代女性。在这幅画中，年轻女子的脸庞明亮，色彩饱和，与深色的外套和书籍封面形成鲜明对比，体现了雷诺阿早期的印象派画风。"
     ],
