     "id": "e084",
     "order": 5,
     "name": "女人与猫",
     "artist": "皮埃尔·博纳尔",
     "artistId": "bonnard",
     "year": 1912,
     "yearLabel": "约 1912",
     "school": "纳比派",
     "medium": "布面油画",
     "dims": "78 × 77.5 cm",
     "workCount": 1,
     "intro": [
      "女人与猫，创作于约1912年，高78cm，宽77.5cm。",
      "博纳尔爱狗，但在绘画中，却对身形柔软、慵懒神秘的猫更感兴趣。很久以前在法国，只有贵族才能养猫，到了博纳尔的时代，猫已经成为很多法国家庭喜爱的宠物了。此画描绘博纳尔的妻子玛尔特和一只爬上餐桌的猫。猫的眼神狡黠，前腿半抬，似乎在注视着主人，等待从盘子里偷鱼的最佳时机。"
     ],
