     "intro": [
      "费利克斯·瓦洛东像，创作于约1900年，高64.5cm，宽50.5cm。",
      "1900年纳比派分裂后，维亚尔的艺术风格和主题发生变化，逐渐回归自然主义，开始更多在户外创作。在描绘室内场景时，色彩和光线也变得更加丰富。画作的风格不再像之前那么抽象、简化，人物的五官也变得更加清晰。对比前面两幅维亚尔作品，这件为好友瓦洛东绘制的肖像，就明显体现了他的风格转变。"
     ],
