     "intro": [
      "乔治·拉孔布，堇紫色海浪，创作于1895-1896年，高73.5cm，宽92.5cm。",
      "乔治·拉孔布出身凡尔赛的富裕家庭，学生时代在天主教学校接受了严格的宗教教育，但他本人后来却自称不可知论者。1892年，拉孔布通过共同好友认识了塞律西埃，后来加入了纳比派。",
      "拉孔布的纳比派生涯只持续了5年，但这短暂时期却奠定了他在艺术史上的地位。作为一名没有宗教信仰的神秘主义者，他的画中充满令人惊叹的象征元素。由于热衷雕塑，在纳比派中，拉孔布也被称为“纳比雕塑家”。"
     ],
