     "id": "e093",
     "order": 14,
     "name": "脱睡裙的女人",
     "artist": "费利克斯·瓦洛东",
     "artistId": "vallotton",
     "year": 1900,
     "yearLabel": "1900",
     "school": "纳比派",
     "medium": "布面油画",
     "dims": "55.5 × 30.5 cm",
     "workCount": 1,
     "intro": [
      "脱睡裙的女人，创作于1900年，高55.5cm，宽30.5cm。",
      "1900年前后，瓦洛东时而绘制气氛紧张的画作，时而创作气氛幽沉的版画。他常用幽暗的光线展现私密生活的瞬间，这种手法源自他精湛的版画技艺。在瓦洛东的作品中弥漫着一种无声的窥探感，虽然时常令人不安，但并不伤人。",
      "这幅画中女子可能是瓦洛东的妻子加布丽埃勒，她正准备脱下长睡裙。衣物洁白的光辉在画面柔和的色调中尤为突出。房间里紧闭的门似乎隐藏着某种秘密。画家邀请我们窥视那些本应隐藏的私人时刻。1900年，瓦洛东购入了一台柯达口袋相机，开始尝试摄影。他的妻子乐于参与拍摄，在平凡的日常生活中为他提供灵感。"
     ],
